class AppButton3D(Button):

    def __init__(self, **kwargs):
        super().__init__(**kwargs)

        self.background_normal = ""
        self.background_color = (0, 0, 0, 0)
        self.color = (1, 1, 1, 1)
        self.font_size = "18sp"

        # 🔥 Shadow + Button
        with self.canvas.before:

            # Shadow (dark layer)
            Color(0, 0, 0, 0.25)
            self.shadow = RoundedRectangle(
                pos=(self.x, self.y - 4),
                size=self.size,
                radius=[20]
            )

            # Main Button
            Color(0.2, 0.7, 1, 1)
            self.bg = RoundedRectangle(
                pos=self.pos,
                size=self.size,
                radius=[20]
            )

        self.bind(pos=self.update_graphics, size=self.update_graphics)

        # 🔥 press effect
        self.bind(on_press=self.press_effect)
        self.bind(on_release=self.release_effect)

    def update_graphics(self, *args):
        self.bg.pos = self.pos
        self.bg.size = self.size

        self.shadow.pos = (self.x, self.y - 4)
        self.shadow.size = self.size

    # 🔥 Button press animation
    def press_effect(self, *args):
        Animation.cancel_all(self)

        anim = Animation(y=self.y - 3, duration=0.05)
        anim.start(self)

    def release_effect(self, *args):
        Animation.cancel_all(self)

        anim = Animation(y=self.y + 3, duration=0.05)
        anim.start(self)



















