def wrap(text, max_len=30):
    words = str(text).split()
    lines = []
    line = ""

    for w in words:
        if len(line + w) < max_len:
            line += w + " "
        else:
            lines.append(line)
            line = w + " "

    if line:
        lines.append(line)

    return lines











